assign_labels <- function(code, data) {

  labels <- var_label(data)
  
  to_assign <- vapply(code,
                      function(x) gsub("^.*: ", "", labels[[x]]),
                      character(1))
  
  return(to_assign)
}

create_cross_table <- function(item1, item2 = NULL, data, share = TRUE) {
  dt1 <- extract(item1, data)
  
  # Das saubere Label der ersten Frage für die Spaltenbeschriftung
  label1 <- sub("[0-9]+\\.[0-9]+\\s?", "", item1$label)
  
  # =======================================
  # 1. UNIVARIATER FALL
  # =======================================
  if (is.null(item2) || (is.character(item2) && item2 == "none")) {
    tbl <- tbl <- as.data.frame(table(dt1$answer, useNA = "ifany"))
    
    if (share) {
      # Berechne Prozente und formatiere sie mit "%" Zeichen
      tbl$Freq <- (tbl$Freq / sum(tbl$Freq)) * 100
      tbl$Freq <- sprintf("%.1f %%", tbl$Freq)
      col2_name <- "Anteil"
    } else {
      # Als Ganzzahl erzwingen (verhindert Kommastellen bei Anzahlen)
      tbl$Freq <- as.integer(tbl$Freq)
      col2_name <- "Anzahl"
    }
    
    # Spalten schön benennen!
    colnames(tbl) <- c(label1, col2_name)
    return(tbl)
  }
  
  # =======================================
  # 2. BIVARIATER FALL
  # =======================================
  dt2 <- extract(item2, data)
  forplot <- dt1[dt2, on = "id"]
  
  # Basis-Kreuztabelle
  tbl <- table(forplot$answer, forplot$i.answer, useNA = "ifany")
  
  if (share) {
    # Zeilenprozente berechnen (margin = 1) - passend zu deinem Plot!
    tbl <- prop.table(tbl, margin = 1) * 100
    tbl_df <- as.data.frame.matrix(tbl)
    
    # Alle Spalten mit "%" formatieren
    tbl_df[] <- lapply(tbl_df, function(x) sprintf("%.1f %%", x))
  } else {
    tbl_df <- as.data.frame.matrix(tbl)
    # Alle Spalten als Ganzzahlen formatieren
    tbl_df[] <- lapply(tbl_df, as.integer)
  }
  
  return(tbl_df)
}

create_deck <- function(data, codebook, scales) {
  card_list <- list()
  
  for (i in seq_len(nrow(codebook))) {
    row <- codebook[i, ]
    item_code <- as.character(row$item)
    
    # Skip if the variable does not exist in the loaded data
    if (!any(grepl(item_code, names(data)))) next 
    
    card <- list(name = item_code, label = row$label)
    
    # For MULTIPLE CHOICE items
    if (row$class == "multiple") {
      card$prefix <- paste0("^", item_code, "_")
      class(card) <- c("multiple_choice", "categorical")
      
      # For SINGLE CHOICE 
    } else if (row$class == "single") {
      
      if (!is.na(row$scale) && row$scale %in% names(scales)) {
        # CASE 1: Ordinal Scale (e.g., freq, intens)
        card$levels <- scales[[row$scale]]
        class(card) <- c("ordinal", "single_choice")
        
      } else if (!is.na(row$scale) && row$scale == "categorical") {
        # CASE 2: Categorical (e.g., Geschlecht / Gender)
        class(card) <- c("single_choice", "categorical")
        
      } else if (!is.na(row$scale) && (row$scale == "numerical" || row$scale == "numeric")) {
        # CASE 3: Numeric (e.g., Alter / Age) - Now INSIDE the 'single' block!
        
        # 1. Remove any blank spaces from the string (e.g., "59, 69" -> "59,69")
        breaks_clean <- gsub(" ", "", as.character(row$breaks))
        
        # 2. Split the string and convert it into a numeric vector
        card$breaks <- as.numeric(strsplit(breaks_clean, ",")[[1]])
        
        # 3. Assign the specific class
        class(card) <- c("numeric", "single_choice")
      }
    }
    
    # Save the card to the deck (Outside of all if/else blocks!)
    card_list[[item_code]] <- card
  }
  
  return(card_list)
}

